function safeSrc(v){if(typeof v!=="string"||!v.trim())return "";try{if(v.startsWith("http://")||v.startsWith("https://"))return v;let p=v.trim().replace(/^\/+/, "");if(p.toLowerCase().startsWith("apps/"))p=p.slice(5);else if(p.toLowerCase().startsWith("app/"))p=p.slice(4);const u=new URL(p,CDN_ROOT);return u.protocol==="https:"?u.href:""}catch{return ""}}function safeImage(v){if(typeof v!=="string"||!v)return "";if(v.startsWith("http://")||v.startsWith("https://"))return v;let p=v.replace(/^\/+/, "");if(p.toLowerCase().startsWith("data/app-icons/"))p=p.slice(15);else if(p.toLowerCase().startsWith("appicon/"))p=p.slice(8);return CDN_ROOT+"data/app-icons/"+p}function toast(t){const n=document.createElement("div");n.className="toast";n.textContent=t;$("#toast-stack").append(n);setTimeout(()=>n.remove(),2800)}
