async function sendBugReport(){const category=$("#bug-category").value,title=$("#bug-title").value.trim(),details=$("#bug-details").value.trim(),pageUrl=$("#bug-page").value.trim(),honeypot=$("#bug-website").value,status=$("#bug-report-status"),button=$("#bug-submit");if(!title||!details){toast("Add a title and some details first.");return}button.disabled=true;status.textContent="Sending report…";try{const response=await fetch("/api/bug-report",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({category,title,details,page:pageUrl||location.href,website:honeypot})});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||"Email delivery is not configured yet.");status.textContent="Report sent successfully to both inboxes.";$("#bug-report-form").reset();toast("Bug report sent.")}catch(error){status.textContent=error.message;toast(error.message)}finally{button.disabled=false}}
