let updateNoticeShown=false;
async function checkForUpdates(){const status=$("#update-indicator");try{const [installedResponse,latestResponse]=await Promise.all([fetch("/arcade/version.json",{cache:"no-store"}),fetch("/api/version",{cache:"no-store"})]);if(!installedResponse.ok||!latestResponse.ok)throw Error("Update service unavailable");const installed=await installedResponse.json(),latest=await latestResponse.json();if(!installed.sha||!latest.sha)throw Error("Version information missing");if(installed.sha!==latest.sha){if(status){status.textContent="Update available";status.classList.add("update-needed");status.dataset.action="update-app";status.title="A newer version is available. Click to refresh."}if(!updateNoticeShown){toast("A Solaris update is available. Click the update indicator to refresh.");updateNoticeShown=true}}else if(status){status.textContent="Up to date";status.classList.remove("update-needed");status.removeAttribute("data-action");status.title="Solaris is up to date"}return installed.sha===latest.sha}catch(error){if(status){status.textContent="Update check unavailable";status.title="Could not contact the update service."}return null}}
