function startActivity(kind){
 const sets={
  math:{title:"Math Sprint",tag:"MATHEMATICS",make(){const a=2+Math.floor(Math.random()*18),b=2+Math.floor(Math.random()*18),op=Math.random()<.5?"+":"−";return {q:"What is "+a+" "+op+" "+b+"?",a:op==="+"?a+b:a-b};}},
  words:{title:"Word Builder",tag:"ENGLISH",words:["triangle","planet","library","fraction","gravity","equation","compass","journey"],make(){const word=this.words[Math.floor(Math.random()*this.words.length)];return {q:"Unscramble this word: "+word.split("").sort(()=>Math.random()-.5).join(" "),a:word};}},
  geometry:{title:"Shape Challenge",tag:"GEOMETRY",make(){const q=[["How many degrees are in a right angle?","90"],["How many sides does a hexagon have?","6"],["How many degrees are in a triangle's angles altogether?","180"],["How many parallel sides does a rectangle have?","2 pairs"],["What is a 3D shape with 6 square faces called?","cube"]];const x=q[Math.floor(Math.random()*q.length)];return {q:x[0],a:x[1]};}},
  algebra:{title:"Equation Solver",tag:"ALGEBRA",make(){const x=1+Math.floor(Math.random()*12),a=2+Math.floor(Math.random()*5);return {q:"Solve: "+a+"x = "+(a*x)+". What is x?",a:String(x)};}}
 };
 const game=sets[kind];if(!game)return;let score=0,round=1,current=game.make();
 function draw(){body.innerHTML='<p class="kicker">'+game.tag+' · QUESTION '+round+'/5</p><h2 id="modal-title">'+game.title+'</h2><div class="activity-progress"><span style="width:'+((round-1)*20)+'%"></span></div><p class="activity-question">'+esc(current.q)+'</p><form id="activity-answer-form"><input class="field" id="activity-answer" autocomplete="off" placeholder="Your answer" required><button class="button primary" type="submit">Check answer</button></form><p id="activity-feedback" class="activity-feedback">Score: '+score+'</p>';footer.innerHTML='<button class="button secondary" id="activity-exit">Close</button>';$("#activity-exit").onclick=closeModal;$("#activity-answer-form").onsubmit=e=>{e.preventDefault();const input=$("#activity-answer"),answer=input.value.trim().toLowerCase(),correct=String(current.a).toLowerCase();if(answer===correct){score++;$("#activity-feedback").textContent="Correct! Score: "+score;}else{$("#activity-feedback").textContent="Not quite — answer: "+current.a+". Score: "+score;}if(round===5){$("#activity-answer-form").hidden=true;$("#activity-feedback").textContent="Finished! Final score: "+score+"/5";const again=document.createElement("button");again.className="button primary";again.textContent="Play again";again.onclick=()=>{score=0;round=1;current=game.make();draw()};footer.prepend(again);return;}round++;current=game.make();setTimeout(draw,650);};}
 draw();modal.hidden=false;
}function savePrefs(){const s=settings();s.theme=$("#s-theme").value;s.scale=$("#s-scale").value;s.navPosition=$("#s-nav-position").value;s.libraryLayout=$("#s-library-layout").value;s.clock24=$("#s-clock24").checked;s.accent=$("#s-accent").value;s.animations=$("#s-animations").value;s.compact=$("#s-compact").checked;s.motion=$("#s-motion").checked;s.showDescriptions=$("#s-desc").checked;s.confirm=$("#s-confirm").checked;put("sunset_settings",s);applySettings();toast("Solaris customisation saved.");pageRender()}
